create table public.categorias_productos(id uuid primary key default gen_random_uuid(),nombre text not null unique,descripcion text,orden integer not null default 0,publicado boolean not null default false);
create table public.productos(id uuid primary key default gen_random_uuid(),categoria_id uuid not null references public.categorias_productos(id),nombre text not null,sku text unique,marca text,modelo text,descripcion text,precio numeric(12,2) not null check(precio>=0),existencias integer not null default 0 check(existencias>=0),publicado boolean not null default false,creado_en timestamptz not null default now());
create table public.imagenes_productos(id uuid primary key default gen_random_uuid(),producto_id uuid not null references public.productos(id) on delete cascade,ruta text not null,orden integer not null default 0);
create table public.promociones(id uuid primary key default gen_random_uuid(),producto_id uuid not null references public.productos(id) on delete cascade,titulo text not null,precio_oferta numeric(12,2) not null check(precio_oferta>=0),inicio timestamptz not null,fin timestamptz not null check(fin>inicio),banner_path text,publicado boolean not null default false,orden integer not null default 0);
create table public.especies(id uuid primary key default gen_random_uuid(),nombre text not null,nombre_cientifico text,descripcion text,habitat text,recomendaciones text,imagen_path text,publicado boolean not null default false);
create table public.puntos_pesca(id uuid primary key default gen_random_uuid(),nombre text not null,descripcion text,latitud double precision not null check(latitud between -90 and 90),longitud double precision not null check(longitud between -180 and 180),imagen_path text,publicado boolean not null default false);
create table public.puntos_especies(punto_id uuid references public.puntos_pesca(id) on delete cascade,especie_id uuid references public.especies(id) on delete cascade,primary key(punto_id,especie_id));
create table public.categorias_consejos(id uuid primary key default gen_random_uuid(),nombre text not null unique,descripcion text,orden integer not null default 0,publicado boolean not null default false);
create table public.consejos(id uuid primary key default gen_random_uuid(),categoria_id uuid not null references public.categorias_consejos(id),titulo text not null,resumen text,contenido text,imagen_path text,publicado boolean not null default false,creado_en timestamptz not null default now());
create table public.configuracion(id integer primary key check(id=1),nombre text not null,whatsapp text,direccion text,horarios text,contacto text);
insert into public.configuracion(id,nombre) values(1,'Tharpon MX');
alter table public.categorias_productos enable row level security; revoke all on public.categorias_productos from anon,authenticated; grant select,insert,update,delete on public.categorias_productos to authenticated; create policy lectura on public.categorias_productos for select to authenticated using ((select privado.activo()) and (publicado)); create policy admin on public.categorias_productos for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
alter table public.productos enable row level security; revoke all on public.productos from anon,authenticated; grant select,insert,update,delete on public.productos to authenticated; create policy lectura on public.productos for select to authenticated using ((select privado.activo()) and (publicado and exists(select 1 from public.categorias_productos c where c.id=categoria_id and c.publicado))); create policy admin on public.productos for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
alter table public.imagenes_productos enable row level security; revoke all on public.imagenes_productos from anon,authenticated; grant select,insert,update,delete on public.imagenes_productos to authenticated; create policy lectura on public.imagenes_productos for select to authenticated using ((select privado.activo()) and (exists(select 1 from public.productos p where p.id=producto_id))); create policy admin on public.imagenes_productos for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
alter table public.promociones enable row level security; revoke all on public.promociones from anon,authenticated; grant select,insert,update,delete on public.promociones to authenticated; create policy lectura on public.promociones for select to authenticated using ((select privado.activo()) and (publicado and now() between inicio and fin and exists(select 1 from public.productos p where p.id=producto_id))); create policy admin on public.promociones for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
alter table public.especies enable row level security; revoke all on public.especies from anon,authenticated; grant select,insert,update,delete on public.especies to authenticated; create policy lectura on public.especies for select to authenticated using ((select privado.activo()) and (publicado)); create policy admin on public.especies for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
alter table public.puntos_pesca enable row level security; revoke all on public.puntos_pesca from anon,authenticated; grant select,insert,update,delete on public.puntos_pesca to authenticated; create policy lectura on public.puntos_pesca for select to authenticated using ((select privado.activo()) and (publicado)); create policy admin on public.puntos_pesca for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
alter table public.puntos_especies enable row level security; revoke all on public.puntos_especies from anon,authenticated; grant select,insert,update,delete on public.puntos_especies to authenticated; create policy lectura on public.puntos_especies for select to authenticated using ((select privado.activo()) and (exists(select 1 from public.puntos_pesca p where p.id=punto_id) and exists(select 1 from public.especies e where e.id=especie_id))); create policy admin on public.puntos_especies for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
alter table public.categorias_consejos enable row level security; revoke all on public.categorias_consejos from anon,authenticated; grant select,insert,update,delete on public.categorias_consejos to authenticated; create policy lectura on public.categorias_consejos for select to authenticated using ((select privado.activo()) and (publicado)); create policy admin on public.categorias_consejos for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
alter table public.consejos enable row level security; revoke all on public.consejos from anon,authenticated; grant select,insert,update,delete on public.consejos to authenticated; create policy lectura on public.consejos for select to authenticated using ((select privado.activo()) and (publicado and exists(select 1 from public.categorias_consejos c where c.id=categoria_id and c.publicado))); create policy admin on public.consejos for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
alter table public.configuracion enable row level security; revoke all on public.configuracion from anon,authenticated; grant select,insert,update,delete on public.configuracion to authenticated; create policy lectura on public.configuracion for select to authenticated using ((select privado.activo()) and (true)); create policy admin on public.configuracion for all to authenticated using ((select privado.es_admin())) with check ((select privado.es_admin()));
create index productos_categoria_idx on public.productos(categoria_id);create index imagenes_producto_idx on public.imagenes_productos(producto_id);create index promociones_producto_idx on public.promociones(producto_id);create index puntos_especies_especie_idx on public.puntos_especies(especie_id);create index consejos_categoria_idx on public.consejos(categoria_id);;
